import{_ as E,l,o as i,c as o,v as e,p as n,x as t,d as m,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const w=JSON.parse('{"title":"等风险贡献 ERC","description":"","frontmatter":{"title":"等风险贡献 ERC","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/erc.md","filePath":"quant/erc.md","lastUpdated":1789023840000}'),d={name:"quant/erc.md"};function h(c,a,C,R,u,g){const r=l("Mermaid");return i(),o("div",null,[a[1]||(a[1]=e('<h1 id="等风险贡献-erc" tabindex="-1">等风险贡献 ERC <a class="header-anchor" href="#等风险贡献-erc" aria-label="Permalink to &quot;等风险贡献 ERC&quot;">​</a></h1><div class="epigraph"><p>让每一项资产对组合波动的欧拉贡献相等，得到的权重介于等权与最小方差之间；它是一个有唯一内点解的凸问题，而不是把名义 60/40 改名为「风险平价」。</p><footer>—— Maillard, Roncalli and Teiletche, The Properties of Equally Weighted Risk Contribution Portfolios, Journal of Portfolio Management, 2010</footer></div><p><a href="/quant/risk-parity">风险平价</a> 一文写的是配置哲学与杠杆产品：<a href="/quant/markowitz">Markowitz</a> 丢掉 \\(\\mu\\) 之后，用风险贡献代替名义权重去分散。本篇把其中的数学对象单独拿出来：等风险贡献（Equal Risk Contribution, ERC）。Maillard、Roncalli 与 Teiletche（2010）给出定义、与逆波动 / 最小方差的夹逼、以及与对数障碍的联系。Qian（2005, 2006）从可加的风险预算讲起，ERC 是预算向量 \\(b=\\mathbf{1}/N\\) 的特例。<a href="/quant/risk-budgeting">风险预算</a> 把 \\(b\\) 放开；<a href="/quant/hrp">HRP</a> 把「平」改到树上。这里只把 \\(w\\circ(\\Sigma w)=\\lambda\\mathbf{1}\\) 写清楚：存在唯一性、算法、嵌套、以及多空时会计如何破。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>给定正定 \\(\\Sigma\\) 与单纯形 \\(w\\gt 0,\\mathbf{1}^\\top w=1\\)，最小方差把质量堆到低波动、低相关的角上；等权忽略 \\(\\Sigma\\)；逆波动 \\(w_i\\propto 1/\\sigma_i\\) 忽略相关。ERC 要求</p> \\[w_i(\\Sigma w)_i = w_j(\\Sigma w)_j \\qquad \\forall i,j, \\]<p>即每项对 \\(\\sigma^2(w)=w^\\top\\Sigma w\\) 的欧拉贡献相同（对 \\(\\sigma\\) 的贡献在正权重下是同一组条件）。问题是：这个非线性方程组是否有唯一解、如何计算、相关结构如何改变相对逆波动的偏离，以及当资产列表把同一风险源切成许多名字时，等贡献会不会变成假分散。</p><p>「风险平价」在营销里常等于「股票与债券各出一半波动再加杠杆」。那是 \\(N=2\\) 或资产类层的 ERC，外加一个模型外的融资决策。个股层 \\(N=300\\) 的 ERC 是另一个组合：每只股票 \\(1/300\\) 的贡献，高相关科技股会重复占预算。对象必须先声明是哪一张资产表上的等贡献，否则无法对照。</p><h3 id="欧拉会计是前提" tabindex="-1">欧拉会计是前提 <a class="header-anchor" href="#欧拉会计是前提" aria-label="Permalink to &quot;欧拉会计是前提&quot;">​</a></h3><p>组合波动 \\(\\sigma(w)\\) 正齐次，欧拉公式 \\(\\sigma=\\sum_i w_i\\partial\\sigma/\\partial w_i\\) 让贡献可加、可报 \\(100\\%\\)。若风险度量不是齐次的，或权重有现金项使映射仿射，「贡献之和等于总风险」失败，钉 \\(1/N\\) 没有会计意义。CVaR 在正齐次的版本上可以定义 ERC 式贡献，但估计与优化都换成尾部对象，见 <a href="/quant/cvar-opt">CVaR 优化</a>；2010 年这篇 JPM 的对象是波动。报告用 VaR、优化用 \\(\\sigma\\)，平的是另一张账。</p><p><span class="marginnote">对 \\(\\sigma^2\\) 的贡献 \\(w_i(\\Sigma w)_i\\) 与对 \\(\\sigma\\) 的贡献只差一个共同因子 \\(\\sigma\\)，正权重下等贡献约束相同。允许权重为负时，贡献可负，等贡献方程组可以没有正权重那套直觉解。多空要改成多头预算与空头预算分开，或对 \\(|w_i|\\) 的暴露做预算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Maillard 等人证明：在 \\(w\\gt 0\\)、\\(\\Sigma\\) 正定下 ERC 存在且唯一，并且落在等权与最小方差的「之间」——用总波动与集中度刻画，不是逐分量不等式。相关全相等时，ERC 退回逆波动；波动全相等时，相关更低的资产拿更高权重。等价优化包括最小化贡献两两差的平方，以及带对数障碍的方差最小化</p> \\[\\min_{w\\gt 0}\\ \\tfrac12 w^\\top\\Sigma w \\quad\\text{s.t.}\\quad \\sum_i \\ln w_i \\ge c, \\]<p>适当 \\(c\\) 时 KKT 给出 \\(w\\circ(\\Sigma w)=\\lambda\\mathbf{1}\\)。对数项阻止权重坍到零，这是相对最小方差最关键的正则：GMV 可以稀疏，ERC 在内点不能。</p><p>数值。循环坐标（CCD）：固定其余，按该资产贡献相对 \\(1/N\\) 的缺口缩放 \\(w_i\\)，再投影到单纯形；或牛顿法解 \\(f(w)=w\\circ(\\Sigma w)-\\lambda\\mathbf{1}\\)。\\(\\Sigma\\) 病态时牛顿的 Jacobian 差，应先收缩或因子化。嵌套 ERC：先在资产类之间做 ERC，再在类内做 ERC（或类内市值）。类的 \\(\\Sigma\\) 用类代表组合的协方差。嵌套改变的是「谁算一项」：\\(N\\) 从个股变成类，重复计数被政策切掉。这与 HRP 的树不同：嵌套的切法是经济分类，HRP 的切法是样本聚类。</p><h3 id="从特征组合看一阶条件" tabindex="-1">从特征组合看一阶条件 <a class="header-anchor" href="#从特征组合看一阶条件" aria-label="Permalink to &quot;从特征组合看一阶条件&quot;">​</a></h3><p>\\((\\Sigma w)_i\\) 是资产 \\(i\\) 的边际方差。ERC 要求权重与边际方差成反比：\\(w_i\\propto 1/(\\Sigma w)_i\\)。这是一种均衡：没有资产还能通过微调权重降低「贡献不平等」。最小方差要求 \\(\\Sigma w\\propto\\mathbf{1}\\)，即边际方差全相等，权重大的资产必须是低边际风险的。两者只在特殊 \\(\\Sigma\\) 上重合。把 ERC 写成「带权最小方差」是对的（对数障碍），写成「最小方差的近似」是错的——目标不同，稀疏性不同。</p><p>实现上 \\(\\Sigma\\) 用 <a href="/quant/ewma-cov">EWMA</a>、因子模型或收缩样本。ERC 对 \\(\\Sigma\\) 的估计误差敏感，只是不估 \\(\\mu\\)。用未收缩样本协方差做个股 ERC，会精确地把噪声相关当成「重复」，把噪声低波动当成「便宜风险单位」。先修 \\(\\Sigma\\)，再解等贡献，顺序与 Markowitz 相同，只是下游求解器换了。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是压缩高波动、高相关资产的权重，直到其 \\(w_i(\\Sigma w)_i\\) 降到与其他资产相同。相关块内的多个名字会互相抬高边际风险，因而块内总权重被压低、块内部分摊——ERC 在块内是「摊薄」而不是像 MDP / 某些最小方差那样「选代表」。这是与 <a href="/quant/hrp">HRP</a>、最大分散的行为差：同一科技簇，ERC 让每只都占 \\(1/N\\)，HRP 让整簇占一份再内部分；政策若认为「科技是一个风险源」，应嵌套或改 \\(b\\)，而不是在叶子上做平坦 ERC。</p><p>再平衡：\\(\\Sigma_t\\) 变，贡献偏离 \\(1/N\\)，规则会卖出波动已升的资产。这与波动目标同向，在动量市里持续卖赢家。交易频率应由 <a href="/quant/turnover-penalty">换手惩罚</a> 或带宽约束，而不是每次把方程组解到机器精度。评价看样本外已实现贡献是否大致平坦、以及净成本后的波动，不看优化器打印的完美 \\(1/N\\)。</p><p><span class="marginnote">两资产解析解存在：权重是波动与相关的显式函数。债券波动低于股票时，ERC 的债券名义权重高于 50%。加杠杆把两类的绝对波动抬到政策目标，是产品层，不是方程组的一部分。把杠杆前后的夏普拿来论证「ERC 优于 60/40」，必须声明杠杆与融资成本，否则在比较两个不同的可行集。</span></p><h3 id="嵌套、因子与名单依赖" tabindex="-1">嵌套、因子与名单依赖 <a class="header-anchor" href="#嵌套、因子与名单依赖" aria-label="Permalink to &quot;嵌套、因子与名单依赖&quot;">​</a></h3><p>平坦 ERC 的最大缺陷是名单依赖：把一只 ETF 拆成十只成分，预算从一份变成十份，组合向该风险源倾斜。解决是在因子或资产类上做 ERC，个股只承担特异风险上限。因子 ERC 用暴露 \\(x=B^\\top w\\)，要求因子贡献相等，再在 \\(x\\) 的仿射空间里对 \\(w\\) 求二次最小或加特异方差惩罚。这时「一项」是价值、动量、利率，而不是代码。名单被替换成因子表，政治决策从选股名单挪到选因子名单——仍然有切法，只是切得更接近风险模型。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在 \\(w\\ge 0\\) 失败的多空账本上硬套同一方程组。不要把 ERC 写成免估计：\\(\\Sigma\\) 仍在。不要用两年股票–债券相关给三倍杠杆产品做唯一依据。不要与 MDP、最小方差、HRP 互相改名；相关均匀时它们可以碰巧接近，块状相关时行为分叉。<a href="/quant/industry-country-neutral">行业/国家中性</a> 与平坦个股 ERC 冲突：中性钉住块净暴露，ERC 却按叶子贡献要权——应先中性再在残差风险上预算，或直接在行业因子上 ERC。</p><p>存在唯一性在严格正权重、正定 \\(\\Sigma\\) 下成立。某资产波动极高或与其余相关近 1，最优 \\(w_i\\) 可以非常小，数值上像零；应用带下界的求解并在下界触发时把该资产从集合删除再解，避免在零附近振荡。CVaR-ERC 把 \\(\\Sigma\\) 换成尾部欧拉，样本里少一次崩盘贡献就会跳，比波动 ERC 更要收缩窗口与情景。</p><p><span class="marginnote">Maillard–Roncalli–Teiletche 的贡献是把「风险平价」收成可证明的组合，而不是一个产品商标。内部模型应写 ERC 或 RB(\\(b\\))，并写 \\(\\Sigma\\) 的日期与资产表哈希，避免营销名进入风险报告。</span></p>',29)),(i(),n(p,null,{default:t(()=>[s(r,{id:"mermaid-81",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E6%AD%A3%E5%AE%9A%20%CE%A3%22%5D%20--%3E%20EQ%5B%22w%20%E2%88%98%20(%CE%A3w)%20%3D%20%CE%BB%201%22%5D%0A%20%20EQ%20--%3E%20UNIQ%5B%22w%3E0%20%E6%97%B6%E5%AD%98%E5%9C%A8%E5%94%AF%E4%B8%80%22%5D%0A%20%20IV%5B%22%E9%80%86%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20SPEC%5B%22%E7%9B%B8%E5%85%B3%E5%9D%87%E5%8C%80%E6%97%B6%E9%87%8D%E5%90%88%22%5D%0A%20%20GMV%5B%22%E6%9C%80%E5%B0%8F%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20SPRS%5B%22%E5%8F%AF%E7%A8%80%E7%96%8F%22%5D%0A%20%20EQ%20--%3E%20INT%5B%22%E5%AF%B9%E6%95%B0%E9%9A%9C%E7%A2%8D%20%E2%86%92%20%E5%86%85%E7%82%B9%2C%20%E4%B8%8D%E7%A8%80%E7%96%8F%22%5D%0A%20%20EQ%20--%3E%20NEST%5B%22%E5%B5%8C%E5%A5%97%3A%20%E5%85%88%E7%B1%BB%E5%90%8E%E5%8F%B6%E5%AD%90%22%5D%0A%20%20FLAT%5B%22%E5%B9%B3%E5%9D%A6%E4%B8%AA%E8%82%A1%20ERC%22%5D%20--%3E%20DUP%5B%22%E9%87%8D%E5%A4%8D%E5%90%8D%E5%AD%97%E9%87%8D%E5%A4%8D%E9%A2%84%E7%AE%97%22%5D%0A%20%20NEST%20--%3E%20FIX%5B%22%E5%88%87%E6%B3%95%E6%94%B9%E6%88%90%E7%BB%8F%E6%B5%8E%E5%9D%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ERC 要求 \\(w_i(\\Sigma w)_i\\) 全相等；Maillard、Roncalli 与 Teiletche（2010）证明正权重下存在唯一，并夹在等权与最小方差之间。</li><li>相关均匀时回到逆波动；对数障碍使解保持内点，这是与 GMV 稀疏性的本质差别。</li><li>平坦个股 ERC 名单依赖，应嵌套或在因子暴露上做等贡献。</li><li>多空使欧拉贡献可负，要分腿预算；\\(\\Sigma\\) 仍需收缩，平价不是免估计。</li><li>产品层的股票–债券平价加杠杆，是 \\(N\\) 很小的 ERC 外加融资，不能与个股 ERC 混评。</li><li>出处：Maillard, Roncalli &amp; Teiletche, <em>Journal of Portfolio Management</em>, 2010；风险贡献可加性见 Qian, 2005/2006；算法与预算推广见 Roncalli, <em>Introduction to Risk Parity and Budgeting</em>, 2013。</li></ul>',2))])}const A=E(d,[["render",h]]);export{w as __pageData,A as default};
